-- Jeu de LecteurComposition (« Composition », PROC_COMPO), lot 7 du plan « RIG v3 100 % fonctionnel » (plan-676a4b19).
-- Identifiants 1 702 xxx. Les tables des audiences ont les MEMES definitions que dans PROC_RETAUD.sql (le premier jeu joue les
-- cree, les suivants y ajoutent leurs colonnes), aux types de RIG_DEV (RigDatabase\dbo\Tables\*.sql) ; SIEGER (les juges d'une
-- composition) en plus. Ce qui est retenu ou ecarte, et pourquoi : PROC_COMPO.attendu ; recherches : PROC_COMPO.recherches.
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_AUDIENCE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_AUDIENCE bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_CHAMBRE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_CHAMBRE varchar(5) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_SECTION') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_SECTION varchar(10) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_JUG') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_JUG int NULL;
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF OBJECT_ID(N'v2.CHAMBRE') IS NULL
    CREATE TABLE v2.CHAMBRE (R_CHAMBRE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_CHAMBRE_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CHAMBRE_AVEC_COMPO bit NOT NULL DEFAULT (1));
IF OBJECT_ID(N'v2.SECTION') IS NULL
    CREATE TABLE v2.SECTION (R_SECTION_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_SECTION_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.JUGE') IS NULL
    CREATE TABLE v2.JUGE (JUG_ID_JUG int NOT NULL PRIMARY KEY, JUG_CIVILITE varchar(7) NOT NULL, JUG_NOM varchar(35) NOT NULL, JUG_PRENOM varchar(20) NULL);
IF COL_LENGTH('v2.JUGE', 'JUG_ACTIF') IS NULL ALTER TABLE v2.JUGE ADD JUG_ACTIF bit NOT NULL DEFAULT (1);
IF OBJECT_ID(N'v2.COMPOSITION') IS NULL
    CREATE TABLE v2.COMPOSITION (CMPST_ID_CMAUD int NOT NULL PRIMARY KEY, CMPST_ID_ADNC int NOT NULL, CMPST_NUM_ORDRE smallint NOT NULL,
        CMPST_ID_PRTRP int NULL, CMPST_ID_GRASS int NOT NULL, CMPST_ID_PRQTR int NULL, CMPST_PAR_DEFAUT bit NOT NULL);
IF COL_LENGTH('v2.JUGE', 'JUG_ABREGE') IS NULL ALTER TABLE v2.JUGE ADD JUG_ABREGE varchar(16) NULL;
-- SIEGER a sa cle SGR_ID_SGR, comme RIG_DEV (SIEGER.sql) : l'ecrivain garde la ligne d'un siegeant et n'en change que le juge.
IF OBJECT_ID(N'v2.SIEGER') IS NULL
    CREATE TABLE v2.SIEGER (SGR_ID_SGR int NOT NULL PRIMARY KEY, SGR_ID_CMAUD int NOT NULL, SGR_ID_JUG int NOT NULL, SGR_NUM_ORDRE smallint NOT NULL,
        SGR_TITRE_SIEGEANT varchar(3) NOT NULL);
IF OBJECT_ID(N'v2.GREFFIER_ASSERMENTE') IS NULL
    CREATE TABLE v2.GREFFIER_ASSERMENTE (GRASS_ID_GRASS int NOT NULL PRIMARY KEY, GRASS_ABREGE varchar(16) NOT NULL, GRASS_CIVILITE varchar(7) NOT NULL,
        GRASS_NOM varchar(35) NOT NULL, GRASS_PRENOM varchar(20) NULL, GRASS_ACTIF bit NOT NULL DEFAULT (1));
IF OBJECT_ID(N'v2.PARQUETIER') IS NULL
    CREATE TABLE v2.PARQUETIER (PRQTR_ID_PRQTR int NOT NULL PRIMARY KEY, PRQTR_ABREGE varchar(16) NOT NULL, PRQTR_CIVILITE varchar(7) NOT NULL,
        PRQTR_NOM varchar(35) NOT NULL, PRQTR_PRENOM varchar(20) NULL, PRQTR_ACTIF bit NOT NULL DEFAULT (1));

